// nobloat/ui: the typed UI for editors (JSDoc, checked with // @ts-check), generated by nbui gen from the Go types: do not edit.
// Only types: the markup comes from the Go renderer, or from fragments/ for apps not in Go.

/** @typedef {Object<string, any>} Node any part */
/** @typedef {"archive"|"arrow-down"|"arrow-left"|"arrow-right"|"arrow-up"|"audit"|"bell"|"blocks"|"building"|"calendar"|"camera"|"chart"|"chat"|"check"|"chevron-down"|"chevron-left"|"chevron-right"|"chevron-up"|"clock"|"code"|"cog"|"columns"|"contrast"|"copy"|"cut"|"dashboard"|"dice"|"download"|"edit"|"error"|"euro"|"external"|"eye"|"file"|"filter"|"focus-exit"|"focus"|"folder"|"globe"|"hang-up"|"help"|"home"|"info"|"key"|"link"|"list"|"live-photo"|"lock"|"log-in"|"log-out"|"logs"|"mail"|"menu"|"merge"|"mic"|"minus"|"moon"|"more"|"ok"|"paste"|"pause"|"photo"|"play"|"plus"|"power"|"print"|"redo"|"refresh"|"screen"|"search"|"send"|"signal"|"star-filled"|"star"|"stop"|"sun"|"support"|"tag"|"terminal"|"trash"|"undo"|"unlock"|"upload"|"user"|"users"|"video"|"warning"|"window"|"x"} Icon */

/**
 * Arrow connects two parts in a diagram: Dir right, left, down, up, left-right or up-down; Dashed for what is optional.
 * @typedef {Object} Arrow
 * @property {string} [Dir]
 * @property {boolean} [Dashed]
 * @property {string} [Before] - above and below (horizontal), left and right (vertical)
 * @property {string} [After] - above and below (horizontal), left and right (vertical)
 */

/**
 * Avatar: a person as a picture or their initial; the name sits beside it or in Label.
 * @typedef {Object} Avatar
 * @property {string} [Initial]
 * @property {string} [Img]
 * @property {string} [Label] - when the name is not beside it
 * @property {boolean} [Small]
 */
/** @typedef {BoardColumn[]} Board Board: one column per state; the items are the app's own nodes. */

/**
 * 
 * @typedef {Object} BoardColumn
 * @property {string} [ID]
 * @property {string} [State]
 * @property {string} [Name]
 * @property {string} [New] - the link that creates an item in this column
 * @property {Node[]} [Items]
 */
/** @typedef {Crumb[]} Breadcrumbs Breadcrumbs: the parents with their icons, the current page last (no link). */

/**
 * Button: an action with an icon and a word (Rules: Icons and buttons). With Href it is a link that looks like a button.
 * @typedef {Object} Button
 * @property {string} [Label]
 * @property {Icon} [Icon] - required: every button has one
 * @property {boolean} [Off] - the icon crossed out (mic off)
 * @property {string} [Key] - its shortcut (data-key), shown as a hint on desktop
 * @property {boolean} [Primary] - the one main action of the page
 * @property {boolean} [Danger]
 * @property {boolean} [IconOnly] - the label becomes its name (aria-label) and tooltip (title)
 * @property {boolean} [PhoneIcon] - only the icon on phones (create, edit, delete, copy)
 * @property {boolean} [Toggle] - a switch that stays: aria-pressed with On
 * @property {boolean} [On] - a pressed toggle
 * @property {string} [Badge] - a count on it
 * @property {string} [Href]
 * @property {boolean} [Submit] - type=submit; Form sets it on its actions
 * @property {string} [Name]
 * @property {string} [Value]
 * @property {string} [Popover] - the id of the menu it opens (popovertarget)
 * @property {string} [Dialog] - the id of the dialog it opens (command=show-modal)
 * @property {string} [Form] - the id of the form it submits when it sits outside it (sign out in a menu)
 */

/**
 * Card: a panel with any content; an optional head with the title and one icon-only action (a link to the full list).
 * @typedef {Object} Card
 * @property {string} [Title]
 * @property {number} [Level] - heading level, default 2
 * @property {Button} [Action]
 * @property {Node[]} [Body]
 */

/**
 * Checkbox: one yes or no with its label; several stack in Choices.
 * @typedef {Object} Checkbox
 * @property {string} [Name]
 * @property {string} [Value] - sent when checked; empty is "on"
 * @property {string} [Label]
 * @property {boolean} [Checked]
 */

/**
 * 
 * @typedef {Object} Chip
 * @property {string} [Href]
 * @property {Icon} [Icon]
 * @property {string} [Label]
 * @property {string} [Count]
 * @property {boolean} [On]
 */

/**
 * Chips: filter chips above a list; each a link with its count.
 * @typedef {Object} Chips
 * @property {string} [Label]
 * @property {Chip[]} [Items]
 */
/** @typedef {Checkbox[]} Choices Choices stacks checkboxes. */
/** @typedef {string} Code  */

/**
 * 
 * @typedef {Object} Column
 * @property {string} [Label]
 * @property {string} [Href] - sorts by this column
 * @property {string} [Sort] - "ascending" or "descending" when sorted by it
 * @property {boolean} [Number]
 */

/**
 * 
 * @typedef {Object} Crumb
 * @property {string} [Href]
 * @property {Icon} [Icon]
 * @property {string} [Label]
 */

/**
 * Ctx is one render of one page.
 * @typedef {Object} Ctx
 * @property {string} [Lang]
 * @property {any} [T] - nil: the key is the text
 */

/**
 * Dashboard: the app's start page: stat tiles first, then cards with what needs doing.
 * @typedef {Object} Dashboard
 * @property {StatTile[]} [Tiles]
 * @property {Card[]} [Cards]
 */

/**
 * Dialog: the native <dialog>: a title, any content, the actions; Esc, the backdrop and × cancel. With Action its form posts there; otherwise it closes with the pressed button's value. Open it with a button whose Dialog is its ID.
 * @typedef {Object} Dialog
 * @property {string} [ID]
 * @property {string} [Title]
 * @property {Node[]} [Body]
 * @property {Button[]} [Actions]
 * @property {string} [Action]
 */

/**
 * Drop: a drop zone for files; always names what is allowed (Rules: Forms, uploads).
 * @typedef {Object} Drop
 * @property {string} [Name]
 * @property {string} [Accept] - ".pdf,.png,.jpg"
 * @property {boolean} [Multiple]
 * @property {string} [What] - "Drop invoices here"
 * @property {string} [Or] - "or choose files"
 * @property {string} [Allowed] - "PDF, PNG or JPG, at most 10 MB each"
 */

/**
 * Editable: a value that saves on its own, edited in place (custom element nb-editable). The attr tags are its attributes; a test checks them against observedAttributes in editable.js.
 * @typedef {Object} Editable
 * @property {string} [Label]
 * @property {string} [Value]
 * @property {string} [Type] - input type, default text
 * @property {string} [Unit] - shown after the value
 * @property {string} [Min]
 * @property {string} [Pattern]
 * @property {string} [Error] - what is valid, with an example
 * @property {string} [Name] - the posted name; default the label
 * @property {string} [Action] - where it posts name=value; default the nearest data-action
 * @property {string} [Hint] - the line under it, also where the error shows
 */

/**
 * Empty: what is missing, why, and the way on.
 * @typedef {Object} Empty
 * @property {Icon} [Icon]
 * @property {string} [Title]
 * @property {string} [Text]
 * @property {Button} [Action] - usually the create action
 */

/**
 * 
 * @typedef {Object} Fact
 * @property {string} [Label]
 * @property {Node} [Value]
 */

/**
 * Field: label above, the input, then one line: the hint, or the error in its place (Rules: Forms, Prevent input errors). Err says what is wrong; the hint, shown with it, says what is valid, with an example.
 * @typedef {Object} Field
 * @property {string} [Name]
 * @property {string} [Label]
 * @property {string} [Value]
 * @property {string} [Type]
 * @property {string} [Placeholder] - a realistic sample of the value
 * @property {string} [Hint]
 * @property {string} [Err]
 * @property {boolean} [Required]
 * @property {string} [Autocomplete]
 * @property {string} [InputMode]
 * @property {string} [Pattern]
 * @property {string} [Title] - required with Pattern: a valid example
 * @property {number} [MaxLength]
 */
/** @typedef {string} FieldType FieldType is the input's type; the zero value is text. Date, Time and Code are text fields with their own rules. */

/**
 * Footer: the product and its version left; shortcuts, support and source right.
 * @typedef {Object} Footer
 * @property {string} [App] - nobloat/<App>
 * @property {string} [Version]
 * @property {string} [Changelog] - default /changelog
 * @property {string} [Support] - where to report a problem (the issue form)
 * @property {string} [Source]
 * @property {boolean} [Keys] - the page has shortcuts: show "? shortcuts"
 */

/**
 * Form: a plain POST (or GET) that works without JavaScript; the handler checks it and renders the page again with Err on the fields. Its actions are submit buttons unless they are links (Cancel).
 * @typedef {Object} Form
 * @property {string} [Action]
 * @property {boolean} [Get]
 * @property {Node[]} [Fields]
 * @property {Button[]} [Actions]
 */

/**
 * Header: the app header: logo, Commands (when the page has a palette), the user menu, and the nav under it.
 * @typedef {Object} Header
 * @property {string} [App] - the app's name after the mark
 * @property {string} [Char] - the mark's character, default ◆
 * @property {string} [Home]
 * @property {boolean} [Commands]
 * @property {User} [User]
 * @property {NavItem[]} [Nav]
 */

/**
 * Image: a picture in the flow. Alt says what it shows; Decorative leaves it empty on purpose.
 * @typedef {Object} Image
 * @property {string} [Src]
 * @property {string} [Alt]
 * @property {boolean} [Decorative]
 * @property {number} [Width]
 */
/** @typedef {Fact[]} InfoGrid InfoGrid: facts of an object, label left, value right. */

/**
 * Link: an inline link (Rules: Links). External opens a new tab with the external icon.
 * @typedef {Object} Link
 * @property {string} [Href]
 * @property {string} [Label]
 * @property {boolean} [External]
 */

/**
 * Menu: a popover list of actions, opened by a button with Popover set to its ID.
 * @typedef {Object} Menu
 * @property {string} [ID]
 * @property {MenuItem[]} [Items]
 */

/**
 * MenuItem: a row of a menu or the palette: a link (Href) or a button (Submit with Form, or Dialog to open one). A Line before it separates it from the rows above.
 * @typedef {Object} MenuItem
 * @property {string} [Href]
 * @property {Icon} [Icon]
 * @property {string} [Label]
 * @property {string} [Key]
 * @property {boolean} [Danger]
 * @property {boolean} [Line]
 * @property {string} [Form] - the id of the form it submits (sign out); without Href and Form it is a plain button
 */

/**
 * Message: one sentence, or a bold title and a sentence. Auto closes by itself (never for Danger).
 * @typedef {Object} Message
 * @property {string} [State]
 * @property {string} [Title]
 * @property {string} [Text]
 * @property {boolean} [Auto]
 */

/**
 * Meter: one ratio, with its words.
 * @typedef {Object} Meter
 * @property {string} [Label]
 * @property {string} [Value] - "7,0 of 10 GB"
 * @property {number} [Percent]
 * @property {string} [State]
 */

/**
 * NavItem: one of the app's places in the header's tab bar.
 * @typedef {Object} NavItem
 * @property {string} [Href]
 * @property {Icon} [Icon]
 * @property {string} [Label]
 * @property {string} [Badge]
 * @property {string} [BadgeLabel] - what the badge counts: "3 overdue"
 * @property {boolean} [On]
 */
/** @typedef {Node[]} Nodes Nodes puts several nodes into one slot, separated by a space. */
/** @typedef {string} ObjectID ObjectID: a ticket key in code style with a copy button (Rules: Ids). */

/**
 * Option: one choice of a select, radios or a segmented control.
 * @typedef {Object} Option
 * @property {string} [Value]
 * @property {string} [Label]
 * @property {Icon} [Icon] - segmented only
 * @property {boolean} [Checked]
 */

/**
 * Page: a whole HTML page (layer 3, the shell). With a Header it is an app page (skip link, header with nav and user menu, the page head, main at a readable width, the footer); without one the bare page (sign in, errors).
 * @typedef {Object} Page
 * @property {string} [Title] - the <title>, and the h1 when there is no Head
 * @property {string} [App] - after the title in <title>
 * @property {string} [Static] - where ui.css and ui.js are served; default /static/
 * @property {Header} [Header]
 * @property {PageHead} [Head]
 * @property {Node} [Main]
 * @property {Footer} [Footer]
 * @property {Palette} [Palette]
 * @property {boolean} [Narrow] - a bare page with one small form: sign in, second step, new password
 */

/**
 * PageHead: breadcrumbs below the top level, the title (the page's h1) with its state, and the page's actions; further actions in a More menu (from three on, Rules: Detail).
 * @typedef {Object} PageHead
 * @property {Breadcrumbs} [Crumbs]
 * @property {string} [Title]
 * @property {Status} [State]
 * @property {Button[]} [Actions]
 * @property {MenuItem[]} [More]
 */

/**
 * 
 * @typedef {Object} PageLink
 * @property {string} [Href]
 * @property {string} [Label]
 * @property {boolean} [On]
 */

/**
 * Pager: numbered pages and the position in words. A PageLink without Href is a gap (…).
 * @typedef {Object} Pager
 * @property {string} [Prev]
 * @property {string} [Next]
 * @property {PageLink[]} [Pages]
 * @property {string} [Position] - "21–40 of 128"
 */

/**
 * Palette: the command palette (Ctrl K): a search line over grouped rows. Rows are links or buttons, so they work without its script.
 * @typedef {Object} Palette
 * @property {PaletteGroup[]} [Groups]
 */

/**
 * 
 * @typedef {Object} PaletteGroup
 * @property {string} [Label]
 * @property {MenuItem[]} [Items]
 */
/** @typedef {Node[]} Para Para: a paragraph of running text, mixed with links: Para{Plain("Check "), Link{…}, Plain(" first.")}. */
/** @typedef {string} Plain Plain is text in a slot (escaped); Code the same in code style. */

/**
 * Progress: a task that runs, with what and how far (Rules: Waiting).
 * @typedef {Object} Progress
 * @property {string} [Label] - "Sending newsletter · 312 of 1.200"
 * @property {number} [Percent]
 */

/**
 * Quote: someone else's words, who said them and where.
 * @typedef {Object} Quote
 * @property {string} [Text]
 * @property {string} [Who]
 * @property {string} [Work]
 */

/**
 * Radios: one of a few, all visible, stacked; Label names the group.
 * @typedef {Object} Radios
 * @property {string} [Name]
 * @property {string} [Label]
 * @property {Option[]} [Options]
 */

/**
 * 
 * @typedef {Object} Rank
 * @property {string} [Label]
 * @property {string} [Value] - the formatted number
 * @property {number} [Percent] - of the largest
 */
/** @typedef {Rank[]} Ranked Ranked: parts of a whole as bars, largest first. */

/**
 * 
 * @typedef {Object} Row
 * @property {string} [State]
 * @property {string} [Href]
 * @property {string} [Label]
 * @property {string} [Meta]
 * @property {string} [Number]
 */
/** @typedef {Row[]} Rows Rows: a row list, for short lists of objects with a few facts. */

/**
 * Segmented: one of two to five, side by side; radios underneath, so it works without JavaScript.
 * @typedef {Object} Segmented
 * @property {string} [Name]
 * @property {string} [Label] - the group's name for screen readers
 * @property {Option[]} [Options]
 */

/**
 * Select: one of many in a native select, with a label.
 * @typedef {Object} Select
 * @property {string} [Name]
 * @property {string} [Label]
 * @property {Option[]} [Options] - Checked marks the selected one
 */

/**
 * 
 * @typedef {Object} Setting
 * @property {string} [Label]
 * @property {Node} [Value]
 */

/**
 * Settings: the settings page is only a stack of these sections (Rules: Settings page). Every control saves as it changes: Action is where they post name=value.
 * @typedef {Object} Settings
 * @property {string} [Action]
 * @property {SettingsSection[]} [Sections]
 */

/**
 * 
 * @typedef {Object} SettingsSection
 * @property {string} [Title]
 * @property {string} [Text]
 * @property {boolean} [Danger]
 * @property {Setting[]} [Rows]
 * @property {Button[]} [Actions]
 */

/**
 * StatTile: a number that leads to an action: one link to its list, its change, and a sparkline over Spark or a meter.
 * @typedef {Object} StatTile
 * @property {string} [Href]
 * @property {string} [Label]
 * @property {string} [Value]
 * @property {string} [Delta]
 * @property {string} [State] - of the change: ok, danger …
 * @property {boolean} [Down] - the change goes down
 * @property {number[]} [Spark]
 * @property {string} [Period] - the sparkline's period: required with Spark
 * @property {Meter} [Meter]
 */
/** @typedef {string} State State is what a state colour means; never a hue (Rules: States). */

/**
 * Status: a state as a dot and a word (Rules: never colour alone).
 * @typedef {Object} Status
 * @property {string} [State]
 * @property {string} [Label]
 */

/**
 * 
 * @typedef {Object} Tab
 * @property {string} [Href]
 * @property {Icon} [Icon]
 * @property {string} [Label]
 * @property {boolean} [On]
 */

/**
 * Table: rows people compare across columns. A column with Sort is a link that sorts; Number aligns right.
 * @typedef {Object} Table
 * @property {Column[]} [Columns]
 * @property {Node[][]} [Rows]
 * @property {string} [Total] - the label of the footer row
 * @property {Node[]} [Totals] - the last columns of the footer row
 */

/**
 * Tabs: views of one object as links; the current one is On.
 * @typedef {Object} Tabs
 * @property {string} [Label]
 * @property {Tab[]} [Items]
 */

/**
 * Tag: a user's own word in their colour.
 * @typedef {Object} Tag
 * @property {string} [Href]
 * @property {string} [Label]
 * @property {string} [Color] - #rrggbb
 */
/** @typedef {string} Text Text is an i18n key, resolved in the request's language when the page renders. */

/**
 * ThemeSwitch: auto, light or dark with CSS alone; the server checks the saved one.
 * @typedef {Object} ThemeSwitch
 * @property {string} [Saved]
 */

/**
 * User: who is signed in, from auth's Remote-* headers.
 * @typedef {Object} User
 * @property {string} [Login]
 * @property {string} [Name]
 * @property {string} [Email]
 * @property {string} [Initial]
 * @property {string[]} [Groups]
 * @property {string} [Lang] - the current language
 * @property {string[]} [Langs] - the languages the app has
 * @property {string} [Theme] - "", "light" or "dark"
 * @property {string} [Settings] - the settings page, default /settings
 * @property {string} [SignOut] - where Sign out posts (auth's logout)
 */
